setup.test_logscan.py:
import pytest

from logscan import count_levels, load_entries, top_level


def test_load_entries_parses_each_line():
    entries = load_entries("app.log")
    assert entries[0] == {"ts": "2026-01-01T10:00:00", "level": "INFO", "msg": "started"}
    assert len(entries) == 4


def test_load_entries_skips_blank_lines():
    entries = load_entries("blank.log")
    assert len(entries) == 2
    assert entries[1]["msg"] == "two"


def test_count_levels_counts_occurrences():
    assert count_levels(load_entries("app.log")) == {"INFO": 1, "WARN": 2, "ERROR": 1}


def test_top_level_picks_the_most_frequent():
    assert top_level(load_entries("app.log")) == "WARN"


def test_top_level_breaks_ties_alphabetically():
    assert top_level([{"level": "WARN"}, {"level": "INFO"}]) == "INFO"


def test_top_level_rejects_empty_entries():
    with pytest.raises(ValueError):
        top_level([])


def test_load_entries_rejects_malformed_lines():
    with pytest.raises(ValueError):
        load_entries("bad.log")
